mapper.sql:
AND
(
p.owner_id = #{userId}

OR EXISTS (

SELECT 1

FROM team_member tm

WHERE
tm.team_id = p.team_id
AND tm.user_id = #{userId}
AND tm.member_status = 1
AND tm.role_type IN (
'OWNER',
'ADMIN'
)

)

OR (
EXISTS (

SELECT 1

FROM team_member tm

WHERE
tm.team_id = p.team_id
AND tm.user_id = #{userId}
AND tm.member_status = 1

)
AND EXISTS (

SELECT 1

FROM project_member pm

WHERE
pm.project_id = p.id
AND pm.user_id = #{userId}

)
)
)

mapper.select:
WHERE t.deleted = 0
AND EXISTS (
SELECT 1
FROM task_assignee ta2
WHERE ta2.task_id = t.id AND ta2.user_id = #{userId}
)
AND t.title LIKE CONCAT( '%', #{keyword}, '%' )
AND t.status = #{status}
ORDER BY CASE t.priority WHEN 'URGENT' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'MEDIUM' THEN 3 WHEN 'LOW' THEN 4 ELSE 5 END, CASE WHEN t.deadline IS NULL THEN 1 ELSE 0 END, t.deadline ASC, t.created_time DESC

WHERE t.deleted = 0 AND t.creator_id = #{userId}
AND t.title LIKE CONCAT( '%', #{keyword}, '%' )
AND t.status = #{status}
ORDER BY t.created_time DESC
